/** 
 * Parse the ISUPPORT parameter for server's away message length.
 * @param state the connection state
 * @return returns instance with max away message length or <tt>null</tt> ifnot specified.
 */
private Integer parseISupportAwayLen(final IIRCState state){
  final String value=state.getServerOptions().getKey(ISupport.AWAYLEN.name());
  if (value == null) {
    return null;
  }
  if (LOGGER.isDebugEnabled()) {
    LOGGER.debug("Setting ISUPPORT parameter " + ISupport.AWAYLEN.name() + " to "+ value);
  }
  try {
    return new Integer(value);
  } catch (NumberFormatException e) {
    LOGGER.warn("Invalid number format for AWAYLEN: " + value);
    return null;
  }
}
